package com.logiplatform.service;
import com.logiplatform.dto.OperationsDtos.*; import com.logiplatform.model.*; import com.logiplatform.repository.*; import com.logiplatform.tenancy.TenantContext; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.time.Instant; import java.util.*;
@Service public class ProofOfDeliveryService { private final ProofOfDeliveryRepository pods; private final ShipmentRepository shipments; private final ShipmentService shipmentService; private final NotificationService notifications; public ProofOfDeliveryService(ProofOfDeliveryRepository p,ShipmentRepository s,ShipmentService ss,NotificationService n){pods=p;shipments=s;shipmentService=ss;notifications=n;}
 @Transactional public PodResponse create(PodRequest r){UUID t=TenantContext.getTenantId(); Shipment sh=shipments.findByIdAndTenantId(r.shipmentId(),t).orElseThrow(()->nf("Shipment not found")); if(pods.findByTenantIdAndShipmentId(t,r.shipmentId()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Proof of delivery already exists"); Instant at=r.deliveredAt()==null?Instant.now():r.deliveredAt(); ProofOfDelivery pod=pods.save(new ProofOfDelivery(t,r.shipmentId(),r.tripId(),r.recipientName(),r.recipientPhone(),r.signatureUri(),r.photoUri(),at,r.latitude(),r.longitude(),r.failureReason(),r.notes())); if(r.failureReason()==null||r.failureReason().isBlank()){shipmentService.updateStatus(r.shipmentId(),new com.logiplatform.dto.ShipmentDtos.UpdateStatusRequest("DELIVERED")); notifications.notify(r.shipmentId(),sh.getNotificationEmail(),"Shipment delivered: "+sh.getReferenceCode(),"Proof of delivery was captured for "+sh.getReferenceCode()+".");} else shipmentService.updateStatus(r.shipmentId(),new com.logiplatform.dto.ShipmentDtos.UpdateStatusRequest("ON_HOLD")); return PodResponse.from(pod);}
 @Transactional(readOnly=true) public PodResponse get(UUID shipment){return pods.findByTenantIdAndShipmentId(TenantContext.getTenantId(),shipment).map(PodResponse::from).orElseThrow(()->nf("Proof of delivery not found"));}
 private static ResponseStatusException nf(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);} }
